set title=$txt$Checklist de cobertura de decisões$txt$,resource_type='checklist',summary=$txt$Roteiro para revisar ramos, fronteiras, faixas e casos inválidos antes de considerar uma regra pronta.$txt$,content=$json${"editorial_version":"lc-content-standard-1.0","sections":[{"title":"Cobertura","items":["Existe caso verdadeiro e falso?","Cada ramo foi exercitado?","As fronteiras foram testadas?","Faixas deixam lacunas ou se sobrepõem?","Existe tratamento de dado ausente/inválido?"]},{"title":"Legibilidade","items":["A condição pode ser explicada como frase?","Agrupamentos estão explícitos?","Motivos de recusa são distintos?","Aninhamento é realmente necessário?"]},{"title":"Evidência","body":"Para cada linha da regra, associe um caso de teste que demonstraria um erro se aquela parte estivesse incorreta."}]}$json$::jsonb,status='published'
