set title=$txt$Caderno de bugs — Decisões$txt$,resource_type='exercise',summary=$txt$Casos curtos para localizar condição invertida, faixa inalcançável, OU permissivo, aninhamento excessivo e fallback que mascara dados inválidos.$txt$,content=$json${"editorial_version":"lc-content-standard-1.0","sections":[{"title":"Bug 1 — Fronteira","body":"Regra diz '18 ou mais', implementação usa >18. Identifique o menor caso que prova o erro."},{"title":"Bug 2 — Faixa inalcançável","body":"A cadeia testa nota>=5 antes de nota>=7. Explique por que o segundo ramo fica parcialmente inacessível."},{"title":"Bug 3 — OU permissivo","body":"Acesso exige ativo E admin, implementação usa OU. Monte dois casos de acesso indevido."},{"title":"Bug 4 — Pirâmide","body":"Cinco validações estão aninhadas. Reescreva conceitualmente com guard clauses."},{"title":"Bug 5 — Dado ausente","body":"Campo vazio é convertido para 0 e classificado como não elegível. Separe erro de entrada de resultado da regra."}]}$json$::jsonb,status='published'
